import{_ as e,o as r,c as t,Q as u}from"./chunks/framework.b2e9bf53.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"框架/Vue/VueRouter/介绍.md","filePath":"框架/Vue/VueRouter/介绍.md","lastUpdated":null}'),o={name:"框架/Vue/VueRouter/介绍.md"},a=u('<h2 id="_1-一vue-router概念" tabindex="-1">1.一vue-router概念 <a class="header-anchor" href="#_1-一vue-router概念" aria-label="Permalink to &quot;1.一vue-router概念&quot;">​</a></h2><p>这里的路由并不是指我们平时所说的硬件路由器，这里的路由就是SPA（single page application单页应用）的路径管理器。再通俗的说，vue-router就是WebApp的链接路径管理系统。</p><p>vue-router是Vue.js官方的路由插件，它和vue.js是深度集成的，适合用于构建单页面应用。vue的单页面应用是基于路由和组件的，路由用于设定访问路径，并将路径和组件映射起来。传统的页面应用，是用一些超链接来实现页面切换和跳转的。在vue-router单页面应用中，则是路径之间的切换，也就是组件的切换。路由模块的本质 就是建立起url和页面之间的映射关系。</p><p>（vue Router 是 Vue.js 官方的路由管理器。它和 Vue.js 的核心深度集成，让构建单页面应用变得易如反掌。路由实际上就是可以理解为指向，就是我在页面上点击一个按钮需要跳转到对应的页面，这就是路由跳转）</p><h2 id="_2-为什么不用a标签" tabindex="-1">2.为什么不用a标签 <a class="header-anchor" href="#_2-为什么不用a标签" aria-label="Permalink to &quot;2.为什么不用a标签&quot;">​</a></h2><p>至于我们为啥不能用a标签，这是因为用Vue做的都是单页应用，就相当于只有一个主的index.html页面，所以你写的标签是不起作用的，你必须使用vue-router来进行管理。</p><h2 id="_3-route、routes、router的区别" tabindex="-1">3.route、routes、router的区别 <a class="header-anchor" href="#_3-route、routes、router的区别" aria-label="Permalink to &quot;3.route、routes、router的区别&quot;">​</a></h2><ul><li><p>route：首先它是个单数，译为路由，即我们可以理解为单个路由或者某一个路由；</p></li><li><p>routes：它是个复数，表示多个的集合才能为复数；即我们可以理解为多个路由的集合，JS中表示多种不同状态的集合的形式只有数组和对象两种，事实上官方定义routes是一个数组；所以我们记住了，routes表示多个数组的集合；</p></li><li><p>router：译为路由器，上面都是路由，这个是路由器，我们可以理解为一个容器包含上述两个或者说它是一个管理者，负责管理上述两个；举个常见的场景的例子：当用户在页面上点击按钮的时候，这个时候router就会去routes中去查找route，就是说路由器会去路由集合中找对应的路由；</p></li></ul><h2 id="_4-vue-router作用" tabindex="-1">4.vue-router作用 <a class="header-anchor" href="#_4-vue-router作用" aria-label="Permalink to &quot;4.vue-router作用&quot;">​</a></h2><ol><li><p>根据url锚点路径，在容器中加载不同的模块，本质作用是做页面导航</p></li><li><p>完成SPA（Singal Page Application）的开发</p></li></ol><ul><li>一种特殊的Web应用，它将所有的活动局限于一个web页面中，仅在该Web页面初始化时加载相应的HTML、JS、CSS。</li><li>一旦页面加载完成，SPA不会应为用户的操作而进行页面的重新加载或跳转，而是利用JS动态的转换HTML（采用的是div切换显示和隐藏），从而实现UI与用户的交互。</li></ul>',11),l=[a];function i(s,p,_,n,c,d){return r(),t("div",null,l)}const m=e(o,[["render",i]]);export{v as __pageData,m as default};
